sysevent_in_email_action.script:
(function runAction(/*GlideRecord*/ current, /*GlideRecord*/ event, /*EmailWrapper*/ email, /*ScopedEmailLogger*/ logger, /*EmailClassifier*/ classifier) {

	// Implement email action here
	var catalogItemID = gs.getProperty('x_2307388_it_ass_0.catalog.item.sysid'); 

	var cart = new sn_sc.CartJS();

	var assetType = '';
	if (email.body.asset_type != undefined) {
		if(email.body.asset_type.toLowerCase() == 'network gear') {
           assetType = 'netgear';
		}
		else {
			assetType = email.body.asset_type;
		}
	}

	var consumable = '';
	if(email.body.consumable!=undefined){
		consumable = email.body.consumable.toLowerCase();
	}
	else if(email.body.consumbales!=undefined){
		consumable = email.body.consumbales.toLowerCase();
	}

	var priority = '';
	if(email.body.priority!=undefined){
		var temp = email.body.priority;
		if(temp == 1 || temp.toLowerCase() == 'high')
			priority = 1;
		else if(temp == 2 || temp.toLowerCase() == 'medium')
			priority = 2;
		else if(temp == 3 || temp.toLowerCase() == 'low')
			priority = 3;
	}

	var reqPayload = {
		'sysparm_id': catalogItemID,
		'sysparm_quantity': '1',
		'variables' : {
			'requestor': gs.getUserID(),
			'type_of_asset': assetType,
			'consumables': consumable,
			'priority': priority,
			'company': email.body.company.toLowerCase() || '',
			'short_description': email.subject || '',
			'description': email.body_text
		}
	};

	var rc = cart.orderNow(reqPayload);

	gs.info("Catalog Inbound Action\nUser: " + gs.getUserID()+"\nEmail Content:\n"+
	email.subject+"\n"+email.body.asset_type+"\n"+email.body.company+"\nRecord Created: "+rc);

	var requestSysId = rc.request_id;

	var ritm = new GlideRecord('sc_req_item');
	ritm.addQuery('request', rc.sys_id);
	ritm.query();
	if (ritm.next()) {
        ritm.work_notes = "Request submitted via email from: " + email.origemail + "\n\nEmail Subject: " + email.subject;
        ritm.update();

        sys_email.target_table = "sc_req_item";
        sys_email.instance = ritm.sys_id;
    }

    // 6. Stop processing and abort default insert
    event.state = "stop_processing";
    current.setAbortAction(true);


})(current, event, email, logger, classifier);
